// ROUND 17 -- the FULL essence catalog: every one of the 145 non-confluence
// essences from the user's HWFWM_TTRPG.xlsx "Essences" tab, names and
// rarities verbatim. (The tab's other 101 rows are the confluence essences,
// which are generated rather than bonded and live in awakening.js's
// CONFLUENCE_NAMES.)
//
// GENERATED by gen_round17_essences.py -- edit that, not this.
//
// Every one of the 145 names also exists in the 180-stone catalog, so
// `family`, `color` and `phrase` are reused from there rather than
// re-invented: the concept "Venom" is the same concept whether it arrives
// as a stone or an essence, and `family` is what awakening.js's
// FAMILY_TRAITS reads to bias ability generation. What differs is the
// RARITY (the Essences tab disagrees with the stone tab constantly and is
// authoritative here) and the DESC, which is written in the essence voice
// -- a stone is an object you hold, an essence is something you absorb.
//
// `cube` indexes public/assets/essence_cubes.png (221 cubes). `tint`, when
// present, means this essence shares a cube with another but is recoloured
// to its own theme colour -- the free pool runs 120 deep against 145
// essences, so 25 of them are tinted variants.
//
// The five essences that existed before this round keep their ids
// (fire/might/heal/shadow/avatar) so saves, loot tables and ESSENCE_CUBES
// keep working -- note heal is "Renewal" and shadow is "Dark".
// ROUND 396 -- EVERY `desc` REWRITTEN BY HAND. "The current descriptions sound mass produced instead of custom
// authored": 118 of 148 had been one of 46 slot-in templates ("Absorbing it is a door opening inward onto X",
// "Bonded, the flinch goes out of you and X takes its place"). Each is now one authored statement, checked against the
// confluence matcher so no incidental word ("bonded", "behind", "open", "hands") steers a trio's name. Phrases are
// unchanged (the stone catalogue shares them). The confluences got their first descriptions in confluenceFlavour.js.
export const ESSENCE_CATALOG = {
  // ROUND 73 -- the alchemy essences, the other half of the user's ask. An
  // essence is what a build is BUILT on, so these two are the reason to take
  // the alchemy family at all; the stones sharpen it. `potionCd` is read the
  // same way the stones' is, and is larger, because binding an essence is a
  // whole slot and socketing a stone is a quarter of one.
  //
  // `cube` is the index into the 249-cube essence atlas and MUST BE UNIQUE.
  // Both of these were first written with 49, copied from the row above them,
  // which put three essences on one sprite -- test_round17 caught it as "every
  // essence sprite is visually distinct: 146/148". 103 indices were free.
  // ROUND 78 -- and the second of the two, found by the same comparison.
  // 'Alchemy' is a confluence; 'Reagent' is what the essence actually is --
  // the raw material, where the neighbouring Elixir essence is the finished
  // draught. Same reasoning as `avatar` above: the id is untouched, so the
  // motifs, signatures and slime summon keyed to `essAlchemy` all still land.
  essAlchemy: { name: 'Reagent', rarity: 'Uncommon', family: 'alchemy', color: '#a5d6a7', phrase: 'the patient transmutation', cube: 1, potionCd: 0.2, desc: 'An apprentice\'s earliest lesson: a reaction does not stop because you have looked away from it. You are the flask and the stirring rod now, and whatever you transmute goes on transmuting for days.' },
  essElixir: { name: 'Elixir', rarity: 'Rare', family: 'alchemy', color: '#80deea', phrase: 'the perfected draught', cube: 4, potionCd: 0.25, desc: 'Alchemists squander whole lifetimes chasing one perfect tincture. You have swallowed it, and it has not stopped working: every hurt you or your companions suffer is met, soon afterwards, by something warm already knitting it closed.' },
  // ===== ROUND 216 (item 6) -- ADEPT IS SKILL, NOT THOUGHT =================
  //
  // The user: "Adept essence is about skill, generally dexiterity (bows,
  // daggers, acrobatics, thieves assasins, martial arts) but occasionally
  // magic (magical adept)."
  //
  // It sat in `mind`, beside Knowledge, Magic, Omen and Rune -- a family
  // whose element is SHADOW and whose noun is "thought". That is where
  // "Thought Jaws" and "Reflex of Thought" came from, and why an Adept kit
  // kept producing magical-tools passives.
  //
  // Its own motif has always been right -- levers stalk/swift/shift, parts
  // "footwork", "wrist", "blade-form", "poise", "reflex", "drilled stance",
  // body "the hands stop hesitating, the feet stop being where the blow
  // lands". The family was the only thing disagreeing with it.
  //
  // `motion` is the right home: element PHYSICAL, and the company is Dance,
  // Swift and Foot, which is the acrobatics-and-martial-arts cluster the
  // user's list names. The "occasionally magic" half is not lost by moving --
  // it arrives the way it should, through the stones the player sockets,
  // rather than being baked into what the essence is.
  essAdept: { name: 'Adept', rarity: 'Common', family: 'motion', color: '#90caf9', phrase: 'practiced mastery', cube: 49, desc: 'All those tedious repetitions, repaid in one sum: the reflexes stop asking permission, and the sidestep is finished while the reason for it is on its way.' },
  essApe: { name: 'Ape', rarity: 'Common', family: 'beast', color: '#8d6e63', phrase: 'brute cunning', cube: 116, desc: 'The slouch is not slowness. An ape wins every argument with the longest reach and the nearest rock, and when one of its troop is struck, all of them remember who did it.' },
  essArmour: { name: 'Armour', rarity: 'Common', family: 'guard', color: '#90a4ae', phrase: 'layered steel', cube: 247, desc: 'Armour is a riveted promise to everyone at your back: let the enemy pound on you instead, because you can afford the dents and they cannot.' },
  // ROUND 78 -- 'Aspect', not 'Avatar'. The user: "Avatar should be exclusively
  // a confluence essence. No confluence essence should also be a regular
  // essence." Avatar is in CONFLUENCE_CONCEPTS, so the ESSENCE gives up the
  // name. The id stays `avatar` deliberately: ids are internal and are wired
  // into STARTER_ESSENCES, the hotbar order and a hand-tuned ability, while
  // NAME is the only thing the confluence system matches on -- so renaming the
  // name alone satisfies the rule exactly and costs no content at all.
  // 'Aspect' keeps the identity family's meaning: a face of the self.
  avatar: { name: 'Aspect', rarity: 'Legendary', family: 'identity', color: '#ffd54f', phrase: 'transcendent form', cube: 101, desc: 'Most people die guessing what they truly are; the Aspect refuses to let you. It takes the answer out of you, gilds it, and sets it walking at your side beneath a crown you never dared to claim.' },
  essAxe: { name: 'Axe', rarity: 'Common', family: 'bludgeon', color: '#a1887f', phrase: 'the falling edge', cube: 276, desc: 'Woodcutters know what soldiers forget: you never fight the tree. You choose the angle, let the axehead do the arguing, and step aside from whatever comes down.' },
  essBalance: { name: 'Balance', rarity: 'Uncommon', family: 'order', color: '#b0bec5', phrase: 'perfect equilibrium', cube: 190, desc: 'A true balance is neither cruel nor kind; it only levels. Under this essence the emptiest part of you refills soonest, and the world\'s lopsided accounts begin, without fuss, to come due.' },
  essBat: { name: 'Bat', rarity: 'Common', family: 'flyer', color: '#616161', phrase: 'wings in the dark', cube: 79, desc: 'Blindness stops mattering once you can shriek into a cave and hear its every ledge and sleeper answer back; anything too sluggish to notice needle teeth is a meal you take in sips.' },
  essBear: { name: 'Bear', rarity: 'Common', family: 'beast', color: '#795548', phrase: 'ursine bulk', cube: 260, desc: 'Ursine violence is not a tantrum; it is arithmetic. There is simply more of you than of them, and this essence teaches that sum to your shoulders and to anything trying to get past them.' },
  essBee: { name: 'Bee', rarity: 'Common', family: 'flyer', color: '#fdd835', phrase: 'the tireless swarm', cube: 14, desc: 'A lone bee is an annoyance; a hive is a law of nature. Absorb it and you are the hive, humming with a thousand small furies that leave their stingers in anything foolish enough to swat.' },
  essBird: { name: 'Bird', rarity: 'Common', family: 'flyer', color: '#81d4fa', phrase: 'effortless flight', cube: 137, desc: 'The bargain is struck in the skeleton, which hollows until it is almost nothing: you surrender the heft that kept you planted, and in exchange the air agrees to be a floor.' },
  essChicken: { name: 'Chicken', rarity: 'Common', family: 'flyer', color: '#e8c07d', phrase: 'the stubborn hen', cube: 263, desc: 'Laugh at the hen if you like, right up until you reach for one of her chicks; then a ruffled, squawking tantrum is between you and them, and retreat has never occurred to it.' },
  essBlight: { name: 'Blight', rarity: 'Unknown', family: 'death', color: '#827717', phrase: 'creeping rot', cube: 99, desc: 'Blight never murders anything outright. It simply spreads to the neighbours, and then to their neighbours, until a whole orchard sags under the same sickness.' },
  essBlood: { name: 'Blood', rarity: 'Uncommon', family: 'blood', color: '#c62828', phrase: 'burning blood', cube: 66, desc: 'Blood is the oldest currency in the world, and now you mint it: every wound you leave goes on paying out, hot and red, until the debtor runs dry and your own veins run hotter.' },
  essBone: { name: 'Bone', rarity: 'Uncommon', family: 'death', color: '#e0e0e0', phrase: 'old marrow', cube: 187, desc: 'Every creature walks around with an armoury it has never looked at. Bone teaches you to reach inward for it: ribs that thicken into a cuirass, spurs that burst the skin, and older bones that answer when the marrow summons them.' },
  essBow: { name: 'Bow', rarity: 'Common', family: 'ranged', color: '#a5d6a7', phrase: 'the drawn string', cube: 274, desc: 'Distance used to be your enemy\'s ally. Now every pace of bare country is a pledge in your favour, and the string creaks at your cheek while you decide when to collect.' },
  essBrush: { name: 'Brush', rarity: 'Unknown', family: 'life', color: '#7cb342', phrase: 'wild undergrowth', cube: 60, desc: 'The thicket has never won a battle, and nothing has ever managed to evict it, either. It snags ankles, hooks sleeves, and sends whoever tears through it away bleeding from a hundred small refusals.' },
  essCage: { name: 'Cage', rarity: 'Common', family: 'guard', color: '#78909c', phrase: 'closing bars', cube: 194, desc: 'A cage is a room with strong opinions about who stays in it. Yours clamp around the dangerous ones, and a monster pinned inside them has nobody left to glare at but its keeper.' },
  essCat: { name: 'Cat', rarity: 'Common', family: 'smallbeast', color: '#ffb74d', phrase: 'silent paws', cube: 140, desc: 'Cats do not walk into rooms; they repossess them. The essence lends you that certainty and that soundlessness, along with the habit of deciding exactly when the mouse is told.' },
  essCattle: { name: 'Cattle', rarity: 'Common', family: 'beast', color: '#bcaaa4', phrase: 'patient strength', cube: 17, desc: 'Cattle harbour no grudge against you. They simply plod on together, and anything loitering in the road learns that placid is a great deal heavier than angry.' },
  essChain: { name: 'Chain', rarity: 'Common', family: 'craft', color: '#9e9e9e', phrase: 'binding links', cube: 280, desc: 'Arguments with a chain only go one way. It flies out rattling, comes home taut, and whatever it was sent for comes home with it, agreeable or not.' },
  essClaw: { name: 'Claw', rarity: 'Uncommon', family: 'blade', color: '#ff8a65', phrase: 'rending talons', cube: 149, desc: 'Claws do not cut so much as plough, four ragged furrows to a stroke, each one weeping until the brawl is done.' },
  essCloth: { name: 'Cloth', rarity: 'Common', family: 'craft', color: '#f8bbd0', phrase: 'woven thread', cube: 248, desc: 'Cloth has dressed more injuries than any surgeon and smothered more tyrants than any sword, yet it has never cared which job it was given, so long as the weave held.' },
  essCloud: { name: 'Cloud', rarity: 'Uncommon', family: 'air', color: '#eceff1', phrase: 'drifting vapor', cube: 69, desc: 'Swing at fog and you learn its entire philosophy at once: there is nothing there to injure and nothing to grab, yet somehow you are soaked, lost, and coughing.' },
  essCold: { name: 'Cold', rarity: 'Uncommon', family: 'cold', color: '#b2ebf2', phrase: 'the deep chill', cube: 203, desc: 'Summer is impatient by nature, and cold never has been. It seeps into fingers and gums and the joints of the jaw, until everything near you is wading through winter like syrup.' },
  essCoral: { name: 'Coral', rarity: 'Common', family: 'aquatic', color: '#ff8a80', phrase: 'living reef', cube: 86, desc: 'A reef is a city made by creatures much too small to know it exists. On your skin that masonry never stops, and each blow you weather is laid down as one more stony ridge for the next to chip against.' },
  essCorrupt: { name: 'Corrupt', rarity: 'Epic', family: 'death', color: '#6a1b9a', phrase: 'sweet decay', cube: 214, desc: 'Decay smells sweet for a reason: it is the perfume of one creature being made into supper for another. You have been seated as the guest, and your touch begins setting the table while the supper is up and walking.' },
  essCrocodile: { name: 'Crocodile', rarity: 'Common', family: 'aquatic', color: '#689f38', phrase: 'the patient jaw', cube: 258, desc: 'The crocodile has outlasted every animal that was ever nimbler than it, mostly by knowing the river brings everyone down to drink sooner or later. Then the jaw closes, and the roll begins.' },
  essCrystal: { name: 'Crystal', rarity: 'Rare', family: 'earth', color: '#e1bee7', phrase: 'perfect lattice', cube: 175, desc: 'Crystal is a single law repeated without error, layer on layer. Taken into you, that law leaves no sloppiness anywhere in how you plant your feet, and whatever you splinter fails exactly along the seams you chose.' },
  essDance: { name: 'Dance', rarity: 'Uncommon', family: 'motion', color: '#f48fb1', phrase: 'the endless step', cube: 134, desc: 'The music never really goes away; most people just stop hearing it. You cannot, and in a fight your companions catch the rhythm from you while your enemies trip over their own boots.' },
  shadow: { name: 'Dark', rarity: 'Uncommon', family: 'dark', color: '#7e57c2', phrase: 'devouring shadow', cube: 72, desc: 'Folk say the dark is nothing more than a lamp gone out. They are mistaken: it is a mouth, it has been hungry since the world was young, and it has chosen you to fetch its meals.' },
  essDeath: { name: 'Death', rarity: 'Uncommon', family: 'death', color: '#455a64', phrase: 'the final quiet', cube: 197, desc: 'Death is never cruel and never late; it is simply the one appointment nobody misses. You are its clerk now, and your touch is how the entries are made.' },
  essDeep: { name: 'Deep', rarity: 'Rare', family: 'water', color: '#1a237e', phrase: 'crushing fathoms', cube: 264, desc: 'Fathoms below the last of the daylight, the ocean stops pretending to be kind. That place lives in your chest now, its pressure harmless to you and merciless to anything you drag down there with you.' },
  essDeer: { name: 'Deer', rarity: 'Common', family: 'smallbeast', color: '#bcaaa4', phrase: 'startled grace', cube: 256, desc: 'Everything a deer knows fits inside the snap of a twig. You are three leaps gone while the snap is dying, and whoever crept up on you is left aiming at leaves.' },
  essDimension: { name: 'Dimension', rarity: 'Legendary', family: 'space', color: '#7e57c2', phrase: 'folded space', cube: 164, desc: 'The world was only ever folded paper that believed it was solid. You have learned the creases, and a single step can now arrive across the street, inside a sealed vault, or at an enemy\'s throat.' },
  essDiscord: { name: 'Discord', rarity: 'Epic', family: 'dark', color: '#8e24aa', phrase: 'grinding dissonance', cube: 172, desc: 'A warband stays in tune only by agreement. Discord adds one sour voice, and then you get to listen to the whole choir unravel, each singer certain the others are the ones out of tune.' },
  essDog: { name: 'Dog', rarity: 'Common', family: 'beast', color: '#a1887f', phrase: 'loyal fangs', cube: 107, desc: 'A dog does not ask whether a fight is worth it, only whose fight it is, and if the answer is yours, it is already there with its teeth in somebody\'s ankle.' },
  essDuck: { name: 'Duck', rarity: 'Common', family: 'flyer', color: '#aed581', phrase: 'unbothered calm', cube: 250, desc: 'Hailstones, insults and arrows all slide off oiled down alike, and no one admiring that unruffled serenity ever guesses how furiously the feet are paddling underneath.' },
  essDust: { name: 'Dust', rarity: 'Uncommon', family: 'earth', color: '#bcaaa4', phrase: 'the settling grey', cube: 37, desc: 'Kingdoms all finish as dust, so dust has no reason to be impatient. It works its way into throats, eyelids and crossbow mechanisms, and it buries whole garrisons speck by speck.' },
  essEarth: { name: 'Earth', rarity: 'Common', family: 'earth', color: '#a1887f', phrase: 'jagged stone', cube: 195, desc: 'Any person can be knocked flat, but nobody has ever knocked down a hillside. This essence quietly reclassifies you as the latter, and supplies the jagged stone to make the argument with.' },
  essEcho: { name: 'Echo', rarity: 'Rare', family: 'mind', color: '#b39ddb', phrase: 'returning sound', cube: 188, desc: 'Nothing you do is ever quite over. Each blow, each shout, each footfall comes back a heartbeat late and harder, as though the world cannot stop agreeing with you.' },
  essElemental: { name: 'Elemental', rarity: 'Epic', family: 'identity', color: '#4dd0e1', phrase: 'raw element', cube: 208, desc: 'Other powers sip politely from nature, a cupful here and there. This one couples you straight to the source, and everything you cast runs on unbanked eruption, flood and quake, with nothing to tame them.' },
  essEye: { name: 'Eye', rarity: 'Common', family: 'mind', color: '#4fc3f7', phrase: 'the unblinking gaze', cube: 199, desc: 'Blinking was the gap the world used to sneak things past you, and you have given it up. Whatever your gaze fastens on now learns it has nowhere left to be but exactly where you are looking.' },
  essFeast: { name: 'Feast', rarity: 'Common', family: 'blood', color: '#ff7043', phrase: 'the laden table', cube: 167, desc: 'Warriors who have eaten together fight together. You are the table now: every foe you cut into is another course, and your companions go back to the fray full-bellied.' },
  essFeeble: { name: 'Feeble', rarity: 'Unknown', family: 'death', color: '#9e9e9e', phrase: 'stolen strength', cube: 76, desc: 'Strength was only ever on loan, and your touch demands repayment early: fingers slacken, knees buckle, and the vigour drains out of the foe and into you instead.' },
  fire: { name: 'Fire', rarity: 'Common', family: 'fire', color: '#ff7043', phrase: 'searing flame', cube: 68, desc: 'The same fire that cooks your supper and warms your feet would gladly burn the roof off your house, and wielding it means remembering that those are one favour, not three.' },
  essFish: { name: 'Fish', rarity: 'Common', family: 'aquatic', color: '#4fc3f7', phrase: 'the silver shoal', cube: 259, desc: 'Sharks circle a shoal all day and leave hungry, because a thousand silver glints in perfect unison are always somewhere other than the jaws. You are never only one fish now.' },
  essFlea: { name: 'Flea', rarity: 'Common', family: 'smallbeast', color: '#8d6e63', phrase: 'impossible leaps', cube: 25, desc: 'Ounce for ounce, nothing jumps like a flea, and nothing is harder to get rid of. You have inherited both talents, along with its table manners.' },
  essFlesh: { name: 'Flesh', rarity: 'Uncommon', family: 'blood', color: '#ef9a9a', phrase: 'living meat', cube: 109, desc: 'You stop treating the meat as a temple and start treating it as a workshop: torn sinew reweaves at a thought, an enemy\'s comes apart in your fingers, and you learn exactly how close to the marrow you can cut.' },
  essFoot: { name: 'Foot', rarity: 'Common', family: 'motion', color: '#bcaaa4', phrase: 'the long march', cube: 89, desc: 'Empires have always been conquered at the pace of a marching soldier. Your feet never blister and never quit, and they deliver you a day ahead of any sane estimate, and very quietly.' },
  essFork: { name: 'Fork', rarity: 'Common', family: 'polearm', color: '#b0bec5', phrase: 'the branching point', cube: 8, desc: 'One tine can be dodged; two present a choice, and in the half-heartbeat a foe squanders on choosing, the haft has already pinned it to the dirt.' },
  essFox: { name: 'Fox', rarity: 'Common', family: 'smallbeast', color: '#ff8a65', phrase: 'sly mischief', cube: 114, desc: 'Tales with a fox in them always finish with somebody else wondering where the hens went. You get the feint, the grin, the russet brush, and the pleasure of choosing whose hens.' },
  essFrog: { name: 'Frog', rarity: 'Common', family: 'aquatic', color: '#81c784', phrase: 'sudden springs', cube: 123, desc: 'Everyone mistakes a frog for a lump of mud right up until its tongue snaps out and the fly is abruptly a rumour. One kick of those hind legs later, the mud is squatting three lily pads away.' },
  essFungus: { name: 'Fungus', rarity: 'Common', family: 'life', color: '#bcaaa4', phrase: 'quiet spores', cube: 41, desc: 'Beneath every forest floor sprawls a second forest, finer than cobweb and miles across, deciding unseen which trees thrive and which are eaten. It laces through you now, and it is very thorough.' },
  essGathering: { name: 'Gathering', rarity: 'Rare', family: 'space', color: '#9575cd', phrase: 'drawn-together things', cube: 201, desc: 'Two people can pick over the same vault, and only one walks out laden. The world simply yields more to you, a fuller purse, a richer seam, one more thing left to glean, and nobody working beside you can explain why.' },
  essGlass: { name: 'Glass', rarity: 'Uncommon', family: 'earth', color: '#e0f7fa', phrase: 'fragile clarity', cube: 218, desc: 'Glass never pretends to be tough, and that honesty is its menace: smash it and it does not bruise; it bursts into a hundred keen splinters, each with somewhere to be.' },
  essGoat: { name: 'Goat', rarity: 'Common', family: 'beast', color: '#bcaaa4', phrase: 'sure-footed stubbornness', cube: 135, desc: 'A sheer crag is merely a staircase with opinions, and a palisade is a dare. Whatever the hooves cannot climb over, the skull simply goes through.' },
  essGrowth: { name: 'Growth', rarity: 'Uncommon', family: 'life', color: '#8bc34a', phrase: 'unstoppable growth', cube: 216, desc: 'Ivy does not bargain with a fortress; it climbs, inch by inch and year by year, until the fortress is a green hill. Everything that fights for you now grows with that same patience.' },
  essGun: { name: 'Gun', rarity: 'Common', family: 'ranged', color: '#78909c', phrase: 'the sudden report', cube: 29, desc: 'Powder and shot can win an argument from across a valley, and the loser hears about it afterwards, if at all. Your aim stays level as long as it must, and then the barrel speaks.' },
  essHair: { name: 'Hair', rarity: 'Common', family: 'craft', color: '#8d6e63', phrase: 'ten thousand strands', cube: 75, desc: 'Snapping a hair takes no more than a sigh. Braid ten thousand and they could moor a warship, and you now produce considerably more than ten thousand, every strand eager to wrap around something.' },
  essHammer: { name: 'Hammer', rarity: 'Common', family: 'bludgeon', color: '#6d4c41', phrase: 'the flattening blow', cube: 279, desc: 'Exactly one idea lives in a hammer, and it has been right about it ever since there were smiths: anything is a nail, provided you swing squarely and refuse to stop.' },
  essHand: { name: 'Hand', rarity: 'Common', family: 'craft', color: '#ffcc80', phrase: 'the steady grip', cube: 198, desc: 'Every tool ever made began as a notion in somebody\'s fingers. Yours close on the world the way a craftsman\'s close on tongs: without a tremor, and without letting go until the work is finished.' },
  essHarmonic: { name: 'Harmonic', rarity: 'Epic', family: 'order', color: '#81d4fa', phrase: 'perfect resonance', cube: 62, desc: 'Hum near a slack string and, unbidden, it begins to sing along. You are that hum now: your marrow catches the frequency of every fight, and everything in tune with you answers it louder.' },
  essHeidel: { name: 'Heidel', rarity: 'Common', family: 'beast', color: '#a1887f', phrase: 'tireless hooves', cube: 90, desc: 'Drovers trust the heidel for a reason they can only shrug at: nobody has ever seen one tire. Those haunches are yours now, and their drumming has a way of flattening whatever dithers in the path.' },
  essHook: { name: 'Hook', rarity: 'Common', family: 'polearm', color: '#90a4ae', phrase: 'the catching barb', cube: 285, desc: 'The hook treats the distance to your quarry as a loan. The gaff bites, the haul begins, and every last pace is repaid to your side of the fight, enemy included.' },
  essHorse: { name: 'Horse', rarity: 'Common', family: 'motion', color: '#8d6e63', phrase: 'thundering gallop', cube: 146, desc: 'Half a ton of conviction aimed at the skyline: that is all a gallop is, and whoever wanders into its path discovers, briefly, that conviction comes with hooves.' },
  essHunger: { name: 'Hunger', rarity: 'Rare', family: 'blood', color: '#d32f2f', phrase: 'the empty maw', cube: 165, desc: 'The maw is never full. Feed it one enemy and it is already chewing toward the next, and you walk out of every fight stronger, leaner, and somehow hungrier than you went in.' },
  essHunt: { name: 'Hunt', rarity: 'Common', family: 'mind', color: '#8bc34a', phrase: 'the closing chase', cube: 50, desc: 'The kill is the least of it. Hunting is the art of everything earlier: reading bent grass, staying downwind, and letting the distance shrink so gradually that the quarry never notices it has been cornered.' },
  essIce: { name: 'Ice', rarity: 'Uncommon', family: 'cold', color: '#81d4fa', phrase: 'biting frost', cube: 0, desc: 'Ice is a river that has finished arguing. Your touch persuades everything nearby to reach the same verdict: joints stiffen, steps falter, and at last nothing remains to argue with but a glittering crust.' },
  essIron: { name: 'Iron', rarity: 'Common', family: 'guard', color: '#8b93a6', phrase: 'cold iron', cube: 70, desc: 'Frontier villages hung cold iron above the lintel to warn the scratching things off. You are that iron now, and the scratching things come straight to you instead, and limp away with aching teeth.' },
  essKnife: { name: 'Knife', rarity: 'Common', family: 'blade', color: '#e0e0e0', phrase: 'the hidden edge', cube: 286, desc: 'Swords are for parading; the knife is for the length of a handshake. You no longer walk into a room without a narrow friend up your sleeve and an exact sense of who is within reach.' },
  essKnowledge: { name: 'Knowledge', rarity: 'Uncommon', family: 'mind', color: '#9fa8da', phrase: 'the turning page', cube: 176, desc: 'Flinches, favoured sides, the hitch in a limp: all of it is handwriting, and now you can read it, where a creature is thin, how much it has left, and which way it means to lunge.' },
  essLife: { name: 'Life', rarity: 'Uncommon', family: 'life', color: '#aed581', phrase: 'stubborn vitality', cube: 209, desc: 'Life is the weed prying apart the paving and the seedling poking up through a burnt forest. It never argues with death; it simply outvotes it, and now it casts those votes through you, for everyone at your side.' },
  essLight: { name: 'Light', rarity: 'Uncommon', family: 'light', color: '#ffd54f', phrase: 'blinding light', cube: 98, desc: 'There is no tact in light, and certain things do not survive being seen clearly. Noon walks with you now, and whatever depended on the gloom learns all at once how much it depended.' },
  essLightning: { name: 'Lightning', rarity: 'Uncommon', family: 'storm', color: '#fff176', phrase: 'arcing lightning', cube: 217, desc: 'Lightning does not pick one target when it can pick the nearest, and then whoever is nearest to that. Absorb it and your thoughts catch the habit, leaping ahead of their own conclusions and leaving the room smelling of singed eyebrows.' },
  essLizard: { name: 'Lizard', rarity: 'Common', family: 'serpent', color: '#9ccc65', phrase: 'cold-blooded stillness', cube: 151, desc: 'The quartermaster\'s ledger lists eleven lizard scouts and can only account for four, which is rather the idea. They bask on warm rocks until nobody remembers them, and whoever finally grabs one gets a wriggling scrap of it and no scout.' },
  essLocust: { name: 'Locust', rarity: 'Common', family: 'flyer', color: '#c0ca33', phrase: 'the devouring cloud', cube: 34, desc: 'One locust is a curiosity; ten thousand are weather, and weather does not ask whose barley it is eating. By the next bell the furrows have nothing to grieve but stubble.' },
  essLurker: { name: 'Lurker', rarity: 'Unknown', family: 'dark', color: '#37474f', phrase: 'the watcher below', cube: 213, desc: 'Something lives at the bottom of every lake, below where anyone swims, silt-buried and unlit and perfectly content to be forgotten. You understand it better once you are the one down there, counting ankles.' },
  essMagic: { name: 'Magic', rarity: 'Common', family: 'mind', color: '#ba68c8', phrase: 'raw arcana', cube: 210, desc: 'A pyromancer can sum up his spell in one syllable. An arcanist with this essence needs a pot of tea and a cushion, because the explanation has clauses, like the spell, which runs longer, wider and stranger until every casting has rooms in it.' },
  essMalign: { name: 'Malign', rarity: 'Epic', family: 'dark', color: '#7b1fa2', phrase: 'patient spite', cube: 200, desc: 'A curse is a grudge that has learned to pay rent. Yours takes the room with a crooked mouth and a long memory, and whoever earned it notices each new day arriving a little smaller than the last.' },
  essManatee: { name: 'Manatee', rarity: 'Common', family: 'aquatic', color: '#90a4ae', phrase: 'unhurried drift', cube: 59, desc: 'Old sailors mistook them for mermaids, which says a great deal about the voyage. Blows sink into the same soft ballast under your skin and go nowhere, and you wallow through a brawl as though it were someone else\'s weather.' },
  might: { name: 'Might', rarity: 'Common', family: 'force', color: '#ffab40', phrase: 'overwhelming force', cube: 159, desc: 'Might has no subtlety in it whatsoever. The cart you strained at yesterday tips over today, the jaw you clout stays clouted, and most who take it stop learning anything else, because so few problems survive being picked up.' },
  essMirror: { name: 'Mirror', rarity: 'Uncommon', family: 'identity', color: '#cfd8dc', phrase: 'the answering image', cube: 170, desc: 'Punch a mirror and it punches back from your own angle, with your own astonishment on its face. Anyone who swings at your silvered skin learns this the long way, as their blow comes looking for the way home.' },
  essMonkey: { name: 'Monkey', rarity: 'Common', family: 'smallbeast', color: '#a1887f', phrase: 'clever fingers', cube: 124, desc: 'Travel a road beside one of these and you learn to count the spoons, then to count your companion, who is already up a drainpipe eating your pear. Curious fingers, bored feet, and not one ounce of remorse.' },
  essMoon: { name: 'Moon', rarity: 'Rare', family: 'light', color: '#e8eaf6', phrase: 'the pale tide-puller', cube: 184, desc: 'The moon hauls whole tides without laying a finger on them, and silvers the road alike for the fugitive and the pursuer. It shares that impartial fairness with whoever carries it: stray things lean toward you, and nothing under your pale regard stays unfound.' },
  essMouse: { name: 'Mouse', rarity: 'Common', family: 'smallbeast', color: '#bdbdbd', phrase: 'unseen scurrying', cube: 12, desc: 'A house cat can devote its whole life to mice and die outnumbered. Be small in every way that matters to an enemy, the essence says, and let the whiskers map the exits ahead of the brain.' },
  essMyriad: { name: 'Myriad', rarity: 'Legendary', family: 'space', color: '#b39ddb', phrase: 'countless selves', cube: 186, desc: 'Swing once and feel the blow decide it would rather be three. Myriad is that decision made permanent: one of you swings, several of you arrive, and the outline you were born with has given up counting.' },
  essNeedle: { name: 'Needle', rarity: 'Common', family: 'blade', color: '#eeeeee', phrase: 'the precise point', cube: 51, desc: 'A hauberk is a promise made by a craftsman, and craftsmen are tired by supper. Somewhere near the armpit there is always a laced seam they hurried, and something slender is already through it.' },
  essNet: { name: 'Net', rarity: 'Common', family: 'craft', color: '#a5d6a7', phrase: 'the closing mesh', cube: 100, desc: 'Fishermen say a net is mostly holes, and that this has never yet mattered to a fish. Cord pays out of your fingers, the gaps cinch tight, and whatever thrashes in the middle learns that every way out is tied off.' },
  essOctopus: { name: 'Octopus', rarity: 'Common', family: 'aquatic', color: '#ce93d8', phrase: 'eight patient arms', cube: 261, desc: 'An octopus can pour itself through a gap no wider than a thumb and come out the other side intact and offended. Here a skeleton is negotiable, eight soft grips take whatever you were reaching for, and a sealed room is only a rumour.' },
  essOmen: { name: 'Omen', rarity: 'Epic', family: 'mind', color: '#ffb74d', phrase: 'the read sign', cube: 183, desc: 'An omen is not a warning, because a warning can be heeded. What Omen sends toward an enemy is already late and already certain, and it lands like news nobody wanted, with the whole town somehow knowing.' },
  essPangolin: { name: 'Pangolin', rarity: 'Common', family: 'guard', color: '#bcaaa4', phrase: 'overlapping scales', cube: 82, desc: 'Leopards that corner a pangolin lose an afternoon pawing at it and slink off with sore teeth. Curl up shingled like a chapel roof, and whatever wanted a bite must make do with the attempt.' },
  essPaper: { name: 'Paper', rarity: 'Common', family: 'craft', color: '#fff9c4', phrase: 'the written word', cube: 177, desc: 'Clerks like to say the pen has toppled more kingdoms than the sword, and here they are proved right in small ways: a folded square that catches a cut, a seal set over a mouth, a signature nothing can contest.' },
  essPlant: { name: 'Plant', rarity: 'Common', family: 'life', color: '#81c784', phrase: 'patient rootwork', cube: 205, desc: 'Weeds need only a gap in a flagstone and a summer, and the flagstone loses. Roots work out of your heels the same way, drinking from whatever you are planted in, indifferent to argument and to the calendar.' },
  essPotent: { name: 'Potent', rarity: 'Epic', family: 'force', color: '#ff7043', phrase: 'concentrated power', cube: 73, desc: 'Squeeze a river through a pipe no broader than a finger and it cuts a man in half. Your power, crammed into a matrix that dense, leaves you harder than skin and sinew were ever meant to survive.' },
  essPure: { name: 'Pure', rarity: 'Uncommon', family: 'light', color: '#ffffff', phrase: 'undiluted essence', cube: 196, desc: 'Poison, fever, even a god\'s malediction: none of them is permitted to stay. Whatever crept into you uninvited is scrubbed out and shown the road, and what is left is plainly, stubbornly yours.' },
  essRabbit: { name: 'Rabbit', rarity: 'Common', family: 'smallbeast', color: '#f5f5f5', phrase: 'the bolting sprint', cube: 26, desc: 'A rabbit wins its arguments by not being there for them. Your hind legs fold like a cocked crossbow, your ears lengthen, and trouble arrives to a warm patch of flattened grass.' },
  essRake: { name: 'Rake', rarity: 'Common', family: 'polearm', color: '#a1887f', phrase: 'gathered leavings', cube: 110, desc: 'Gardeners say a rake asks the soil one question per stroke and is always answered with a heap. Long teeth on a long reach comb a crowd of enemies the way they comb autumn, leaving furrows where people stood.' },
  essRat: { name: 'Rat', rarity: 'Common', family: 'smallbeast', color: '#9e9e9e', phrase: 'the surviving swarm', cube: 23, desc: 'Poison the granary, flood the cellar, set terriers on the docks: by next month the rats are back, and there are more of them. Anyone who absorbs it inherits the same disgraceful talent for outlasting everyone who tried.' },
  heal: { name: 'Renewal', rarity: 'Epic', family: 'life', color: '#66bb6a', phrase: 'the turning season', cube: 87, desc: 'Each year the lean season strips the orchard to bare wood and pronounces it finished, and each year it is mistaken. That stubbornness spreads to you and to everyone near you: cuts close the way blossom arrives in April, nowhere, then everywhere.' },
  essResolute: { name: 'Resolute', rarity: 'Rare', family: 'force', color: '#78909c', phrase: 'the planted foot', cube: 84, desc: 'Mountains have never won a fight, only outlasted everyone who started one with them. Plant your feet with the same opinion and whatever wanted past you is obliged to take it up with you in person.' },
  essRune: { name: 'Rune', rarity: 'Epic', family: 'mind', color: '#ffcc80', phrase: 'the graven word', cube: 78, desc: 'Speech is gone within a room\'s length; a rune cut properly goes on repeating itself when the hall is rubble and its language forgotten. The glyphs this essence cuts under your skin never stop talking.' },
  essSand: { name: 'Sand', rarity: 'Uncommon', family: 'earth', color: '#ffe082', phrase: 'numberless grains', cube: 202, desc: 'Cut a dune in half and you have two dunes. Hack at a heap of grit and it pours apart under the stroke, reassembles, and works itself into every buckle and eyelash nearby; that heap is now you.' },
  essSceptre: { name: 'Sceptre', rarity: 'Common', family: 'polearm', color: '#ffd54f', phrase: 'the raised authority', cube: 270, desc: 'No one sharpens a sceptre, and no one has needed to. Bring it up and every soul in earshot recalls that someone here must be obeyed; friends straighten, and enemies discover their mouths have gone dry.' },
  essSerene: { name: 'Serene', rarity: 'Rare', family: 'order', color: '#b2dfdb', phrase: 'untroubled water', cube: 163, desc: 'Toss a pebble into a mountain tarn and the surface forgets it almost at once. So with you: the pulse eases to a measured count, and whatever lands on you sinks without leaving a ripple.' },
  essShark: { name: 'Shark', rarity: 'Common', family: 'aquatic', color: '#78909c', phrase: 'the circling hunger', cube: 252, desc: 'Yank a shark\'s tooth and another row has already shuffled forward. With this essence you circle, and the faintest scratch is the loudest thing for a mile in any direction.' },
  essShield: { name: 'Shield', rarity: 'Common', family: 'guard', color: '#4fc3f7', phrase: 'the raised guard', cube: 246, desc: 'The oldest tactic in the world is a plank between a friend and an arrow. The refinement, which took somewhat longer, is a plank the arrows prefer.' },
  essShimmer: { name: 'Shimmer', rarity: 'Epic', family: 'light', color: '#f8bbd0', phrase: 'dancing light', cube: 174, desc: 'Deceit needs a little dimness to lean on, and Shimmer allows it none: illusions fray into motes, the weak seam in a breastplate glints as if lamplit, and the gloom retreats to a respectful distance.' },
  essShip: { name: 'Ship', rarity: 'Common', family: 'motion', color: '#8d6e63', phrase: 'the leaning sail', cube: 93, desc: 'Canvas sags limp until it leans, and then nothing in the harbour can catch it. Ribs set like a hull, a sheet bellied across your back, and every voyage docks ahead of schedule.' },
  essShovel: { name: 'Shovel', rarity: 'Common', family: 'polearm', color: '#a1887f', phrase: 'turned earth', cube: 3, desc: 'Empires are won by cavalry and secured by ditches, and no bard has ever praised a ditch. For those who need no praise, there is this: it digs, it buries what needs burying, and its flat side lands like a slammed cellar trapdoor.' },
  essSickle: { name: 'Sickle', rarity: 'Common', family: 'blade', color: '#c5e1a5', phrase: 'the curved harvest', cube: 283, desc: 'Reapers never cut stems singly; the curve does that thinking for them. Once your wrist learns it, a crowd at waist level looks a great deal like a ripe crop.' },
  essSin: { name: 'Sin', rarity: 'Legendary', family: 'dark', color: '#880e4f', phrase: 'the cherished wrong', cube: 180, desc: 'Repentance is for vices you have stopped loving. Sin is the one you cannot stop loving: it trots at your heel, takes its tithe from everything your fingers brush, and is fonder of you every year.' },
  essSkunk: { name: 'Skunk', rarity: 'Common', family: 'smallbeast', color: '#424242', phrase: 'the lingering warning', cube: 21, desc: 'Foxes have learned to step around a small striped animal, and the lesson took only once per fox. The stripe is the warning; the reek that clings to attackers for days is the footnote.' },
  essSloth: { name: 'Sloth', rarity: 'Common', family: 'beast', color: '#a1887f', phrase: 'unhurried certainty', cube: 47, desc: 'The jaguar sprints and the hawk stoops, and the sloth outlives them both without leaving its branch. Its hosts stop hurrying entirely; eventually the world gets tired of hurrying at you.' },
  essSmoke: { name: 'Smoke', rarity: 'Uncommon', family: 'dark', color: '#90a4ae', phrase: 'the vanishing veil', cube: 185, desc: 'Smoke cannot be cut, caught or reasoned with; it only thins, and it thins on its own schedule. With it, your outline frays into wisps, and anyone chasing you finishes up coughing in a room with nobody else in it.' },
  essSnake: { name: 'Snake', rarity: 'Common', family: 'serpent', color: '#9ccc65', phrase: 'venomous patience', cube: 255, desc: 'A motionless snake is not an idle one; the idleness is the entire method. Coiled with that patience, you land the strike ahead of the scream.' },
  essSong: { name: 'Song', rarity: 'Uncommon', family: 'order', color: '#f48fb1', phrase: 'the carrying melody', cube: 207, desc: 'Ask any sergeant: a decent refrain has kept more tired soldiers upright than every surgeon in the army. Sung from a barrel chest over the din, it gets into comrades\' feet, which go on remembering the tune when their courage has quite forgotten it.' },
  essSpear: { name: 'Spear', rarity: 'Common', family: 'polearm', color: '#7c93a3', phrase: 'the thrown point', cube: 273, desc: 'Some nameless ancestor sharpened a long stick and invented distance. That old wisdom lives in your elbows now: the lead foot plants unbidden, and nothing gets nearer than the length you choose.' },
  essSpider: { name: 'Spider', rarity: 'Common', family: 'serpent', color: '#616161', phrase: 'the patient web', cube: 125, desc: 'A spider never chases. It rearranges a corner of the world so that running is the mistake, then sits back and lets its guests discover this. Silk from the wrists is the easy part to learn; the temperament is the prize.' },
  essSpike: { name: 'Spike', rarity: 'Common', family: 'blade', color: '#90a4ae', phrase: 'the waiting point', cube: 271, desc: 'Hedgehogs do not attack foxes. They make themselves into a poor decision and let the fox arrive at it. Needles come up through your skin and stay there, so every grab and every clinch is paid for in full.' },
  essStaff: { name: 'Staff', rarity: 'Common', family: 'polearm', color: '#a1887f', phrase: 'the traveler\'s third leg', cube: 269, desc: 'Old highwaymen leave pilgrims be, and tap the gaps in their teeth if you ask why. Hard wood in the fist, a longer step on the road, and both the road and the ruffian come up short.' },
  essStar: { name: 'Star', rarity: 'Rare', family: 'light', color: '#fff59d', phrase: 'the distant fire', cube: 179, desc: 'Tonight\'s starlight set out on its journey when your grandmother\'s grandmother was a child. Something that old and that distant answers when you kindle a pinprick glare, and what it sends down leaves a crater.' },
  essSun: { name: 'Sun', rarity: 'Rare', family: 'light', color: '#ffb300', phrase: 'the noon blaze', cube: 181, desc: 'Midday is honest because it leaves nowhere to skulk, and Sun brings midday along. The earth around you goes bleached and shadowless, and anything relying on a gloomy corner discovers the corners abolished.' },
  essSwift: { name: 'Swift', rarity: 'Common', family: 'motion', color: '#4dd0e1', phrase: 'quicksilver speed', cube: 220, desc: 'Your tendons cinch like rawhide shrinking, and the world starts arriving half a pace late, as though it had paused to tie a bootlace. Enemies reach where you were; you have long since got bored and gone.' },
  essSword: { name: 'Sword', rarity: 'Common', family: 'blade', color: '#d7dee3', phrase: 'the drawn blade', cube: 266, desc: 'Generations of fencing instructors bled to learn what Sword bestows outright. The wrist knows the heft unasked, and the blade leaves its scabbard already halfway through the lesson.' },
  essTechnology: { name: 'Technology', rarity: 'Common', family: 'craft', color: '#80cbc4', phrase: 'clever mechanism', cube: 206, desc: 'Where spells say \'let it be so,\' Technology says \'here is how,\' and shows its working. Your fingers take up a tinkerer\'s rhythm, something under the breastbone begins to tick, and contraptions assemble themselves out of parts you do not remember owning.' },
  essTentacle: { name: 'Tentacle', rarity: 'Epic', family: 'aquatic', color: '#7e57c2', phrase: 'the grasping deep', cube: 257, desc: 'Miles under the surface, in a pressure that has never known daylight, nothing hurries, because nothing seized there ever gets free. Your reach goes boneless and studded with suckers, and learns that lightless patience.' },
  essThread: { name: 'Thread', rarity: 'Common', family: 'craft', color: '#f8bbd0', phrase: 'the binding strand', cube: 40, desc: 'Forty strands can tether an ox that could snap any single one of them, and the ox never works out how. Fine filaments trail from your fingertips now, and anything that brushes them discovers itself stitched into the situation.' },
  essTrap: { name: 'Trap', rarity: 'Common', family: 'craft', color: '#8d6e63', phrase: 'the sprung jaw', cube: 192, desc: 'The finest snare is a choice the victim made unassisted. Tripwires and toothed jaws appear where nothing lay a heartbeat earlier, and other people\'s haste does everything else.' },
  essTree: { name: 'Tree', rarity: 'Common', family: 'life', color: '#66bb6a', phrase: 'the standing green', cube: 18, desc: 'An oak takes a century choosing its spot and three more refusing to leave it. Bark-skinned, its reach as wide as it is tall, it has yet to lose an argument with the weather, and now neither have you.' },
  essTrowel: { name: 'Trowel', rarity: 'Common', family: 'polearm', color: '#bcaaa4', phrase: 'the mason\'s line', cube: 166, desc: 'Walls are never really raised; they are laid, course by course, by someone who refuses to hurry the mortar. A plumb bob swings from your wrist, a mason\'s stubbornness sits in your forearms, and what you set down stays true.' },
  essTurtle: { name: 'Turtle', rarity: 'Common', family: 'guard', color: '#81c784', phrase: 'the patient shell', cube: 53, desc: 'Turtles have outlived dynasties without hurrying and without being got into. Your back roofs over, your neck learns to disappear, and soon companions are crouching in your lee as if you were a boulder.' },
  essVast: { name: 'Vast', rarity: 'Legendary', family: 'space', color: '#9575cd', phrase: 'the borderless whole', cube: 178, desc: 'Remoteness is a courtesy the world extends to small creatures, so they need not consider everything at once. Vast declines the courtesy. Distance stops sending its bill, and every reach of yours widens until it meets something larger, which is rarely.' },
  essVehicle: { name: 'Vehicle', rarity: 'Common', family: 'motion', color: '#90a4ae', phrase: 'the rolling league', cube: 92, desc: 'Some forgotten cartwright taught the road to refund its miles, and Vehicle remembers the method. Your feet are spokes now, the miles run beneath you unasked, and journeys shrink to errands.' },
  essVenom: { name: 'Venom', rarity: 'Uncommon', family: 'serpent', color: '#9ccc65', phrase: 'slow-working poison', cube: 35, desc: 'A cut is an event; venom is a verdict. It enters through a puncture smaller than a freckle and goes on working without you, blackening veins and curdling strength, until your enemy is losing a battle fought entirely inside their own skin.' },
  essVisage: { name: 'Visage', rarity: 'Legendary', family: 'identity', color: '#ce93d8', phrase: 'the worn face', cube: 64, desc: 'A face is merely a habit the skull has fallen into. Lose the habit and the features loosen like wet clay, firming up as someone familiar, someone trusted, someone no witness can ever describe.' },
  essVoid: { name: 'Void', rarity: 'Legendary', family: 'dark', color: '#311b92', phrase: 'the hungry nothing', cube: 191, desc: 'Most absences are content simply to be absent. This one has an appetite. A pit yawns beneath your ribs, the outline of you goes uncertain, and whatever strays close enough begins, without any fuss, to be less.' },
  essWasp: { name: 'Wasp', rarity: 'Common', family: 'flyer', color: '#fdd835', phrase: 'the vindictive sting', cube: 168, desc: 'A bee dies for its sting; a wasp reuses it and remembers who swatted. Your waist nips in, a needle tucks itself beneath the last rib, and you are left with a grudge that can fly.' },
  essWater: { name: 'Water', rarity: 'Common', family: 'water', color: '#29b6f6', phrase: 'crushing water', cube: 204, desc: 'No river has ever hurried, and the canyons are its receipts. The low places in you flood, the lungs learn to take the pressure of depths, and what you send at foes lands like an entire snowmelt arriving at once.' },
  essWhale: { name: 'Whale', rarity: 'Common', family: 'aquatic', color: '#546e7a', phrase: 'the deep song', cube: 265, desc: 'Whalesong travels a hundred leagues, and the family answers. Ribs broaden around one enormous lungful, and a breach is less a leap than a hillside getting to its feet.' },
  essWheel: { name: 'Wheel', rarity: 'Common', family: 'motion', color: '#a1887f', phrase: 'the turning rim', cube: 16, desc: 'Nothing a wheel meets ever gets a second look from it. Your joints quit hinging and begin to revolve, and halting is now the dearer of your two choices.' },
  essWhip: { name: 'Whip', rarity: 'Common', family: 'blade', color: '#8d6e63', phrase: 'the cracking lash', cube: 277, desc: 'That sharp report is the tip of the plait outpacing its own racket. Leather pays out from your forearm like a second wrist, and three paces of distance are three paces of mistake.' },
  essWind: { name: 'Wind', rarity: 'Common', family: 'air', color: '#b2ff59', phrase: 'razor wind', cube: 219, desc: 'The wind is invisible; you know it only by the flattened barley and the roof slates in the lane. Around you, now, the air never quite goes slack, and it is honed fine as a razor.' },
  essWing: { name: 'Wing', rarity: 'Epic', family: 'flyer', color: '#e1f5fe', phrase: 'the beating pinion', cube: 153, desc: 'Children who envy hawks are told to be sensible, and most of them listen. The others, eventually, absorb this: skeletons lightened to reed, backs unfurled into pinions, the earth demoted to somewhere they visit.' },
  essWolf: { name: 'Wolf', rarity: 'Common', family: 'beast', color: '#90a4ae', phrase: 'the pack\'s teeth', cube: 254, desc: 'Lone wolves belong in ballads; real wolves die alone and know it. Your jaw lengthens, your hackles bristle, and everyone running alongside you is another set of teeth on the same animal.' },
  essWood: { name: 'Wood', rarity: 'Unknown', family: 'life', color: '#8d6e63', phrase: 'living grain', cube: 24, desc: 'Old oak, decades out of the forest, goes on twisting toward the way its tree once leaned. Your skin has that stubborn memory now: it toughens like timber, and every gash seals beneath a fresh whorl.' },
  essZeal: { name: 'Zeal', rarity: 'Rare', family: 'force', color: '#ff7043', phrase: 'burning conviction', cube: 272, desc: '\'Spent is solid footing,\' the zealots say, and they mean it as a threat. Every blow you land comes back as vigour and every reserve you exhaust comes back as fresh conviction, until having nothing left is the place you argue from.' },
};

// ===========================================================================
// ROUND 96 -- ESSENCES THAT ARE BUILT AND NOT YET SUPPORTABLE.
//
// The user: "in order for the gun, cyborg and magitech essences to work I need
// to add a variety of guns both modern and scifi. For now lets block those
// essences until everything for them to work is available."
//
// WHAT THE GUN ESSENCE PROMISES AND WHAT THE GAME HAS. Its abilities generate
// off a motif of triggers, barrels, magazines and reports, and the weapon rack
// (weapons.js) holds one thing you could call a gun. A player who bonds it gets
// a kit about shooting and nothing to shoot it with, which is a worse outcome
// than not being able to bond it at all -- and it cannot be fixed here, because
// the missing thing is ART: a spread of firearms, modern and science-fictional,
// with icons, hand poses and projectiles.
//
// Cyborg and Magitech are CONFLUENCE names rather than essences (see
// BLOCKED_CONFLUENCES in awakening.js) and are blocked there for the same
// reason: both are machine confluences whose whole vocabulary is hardware this
// build cannot show you.
//
// HOW THE BLOCK WORKS, and what it deliberately does not do:
//
//   ESSENCE_IDS      -- what the game may GIVE OUT. Blocked ids are absent, so
//                       every drop, every shelf and every roll loses them with
//                       no other file changing.
//   ALL_ESSENCE_IDS  -- what EXISTS. Integrity checks and save-loading read
//                       this, so an old save that already carries a blocked
//                       essence still resolves rather than being emptied on
//                       load. Blocking is not deletion, and a player mid-run
//                       should not lose a slot to a content decision.
//
// TO UNBLOCK: add the firearms, then take the id out of BLOCKED_ESSENCES. There
// is nothing else to undo.
// ===========================================================================
// ROUND 98 -- THE USER: "Guns, technology, magitech and cyborg will have to
// wait. Backburner all of them until I ask again."
//
// Technology is the essence the other three are built out of: Cyborg and
// Magitech are both confluences that need it, and its own kit reads as
// firearms-adjacent. It was working and dropping, which is why it is called out
// here -- this block REMOVES A FUNCTIONING ESSENCE from the game on purpose, at
// the user's word, rather than holding back something incomplete. That is worth
// saying plainly so nobody later reads it as a bug and quietly unblocks it.
export const BLOCKED_ESSENCES = new Set(['essGun', 'essTechnology']);

/** Why each one is held back, so the next person does not have to guess. */
export const BLOCKED_REASON = {
  essGun: 'needs a variety of firearms, modern and science-fictional, before its kit has anything to fire',
  essTechnology: 'held back with the firearms it belongs beside -- it is also what Cyborg and Magitech are made of, so unblocking it alone would re-open two confluences that have nothing to render',
};

/** Everything in the catalogue, blocked or not. Integrity and save-loading. */
export const ALL_ESSENCE_IDS = Object.keys(ESSENCE_CATALOG);

/** Everything the game may hand a player. This is the list every drop, shop and
 *  roll walks, so a blocked essence leaves the game by this one edit. */
export const ESSENCE_IDS = ALL_ESSENCE_IDS.filter(id => !BLOCKED_ESSENCES.has(id));
export const ESSENCE_BY_NAME = Object.fromEntries(
  Object.entries(ESSENCE_CATALOG).map(([id, e]) => [e.name, { id, ...e }]));

// Same ladder the stone catalog uses, plus the sheet's own "Unknown" grade.
export const ESSENCE_RARITY_WEIGHTS = {
  Common: 100, Uncommon: 40, Rare: 14, Epic: 6, Legendary: 2, Unknown: 12,
};
export function rollEssenceDrop(rng = Math.random) {
  const pool = [];
  for (const id of ESSENCE_IDS) {
    const w = ESSENCE_RARITY_WEIGHTS[ESSENCE_CATALOG[id].rarity] || 10;
    pool.push([id, w]);
  }
  const total = pool.reduce((a, [, w]) => a + w, 0);
  let roll = rng() * total;
  for (const [id, w] of pool) { roll -= w; if (roll <= 0) return id; }
  return pool[0][0];
}

/**
 * ROUND 267 -- THE RARITY LADDER, WRITTEN DOWN.
 *
 *   3) "Sereth Vane's drop table should change to any essence uncommon rarity
 *       or higher. With rarity properly weighing the results."
 *
 * `ESSENCE_RARITY_WEIGHTS` has always had the five grades in it, but only as
 * keys of an object, which has no order -- so "or higher" was not a thing any
 * caller could ask. Every floor in the game was therefore spelled as a LIST of
 * the grades that pass (`['Rare','Epic','Legendary']`), which is this project's
 * third fault class: a hand-maintained list beside a generator. Add a sixth
 * grade above Legendary and every one of those lists is silently wrong.
 *
 * `Unknown` is deliberately NOT on the ladder. It is the source sheet's own
 * "we did not grade this one" marker, not a step between two grades -- it
 * weighs 12, between Rare and Uncommon, which is exactly the sort of accident
 * that comes of treating a missing value as a value. It can still be rolled by
 * an unfiltered `rollEssenceDrop`; it just cannot satisfy "Uncommon or higher",
 * because nobody knows whether it is.
 */
export const ESSENCE_RARITY_LADDER = ['Common', 'Uncommon', 'Rare', 'Epic', 'Legendary'];

/** The ids at or above `floor` on the ladder. Empty if `floor` is not on it. */
export function essencesAtLeast(floor) {
  const at = ESSENCE_RARITY_LADDER.indexOf(floor);
  if (at < 0) return [];
  const ok = new Set(ESSENCE_RARITY_LADDER.slice(at));
  return ESSENCE_IDS.filter(id => ok.has(ESSENCE_CATALOG[id].rarity));
}

/**
 * One essence at or above `floor`, drawn ONCE from the eligible pool with each
 * candidate carrying its own rarity's weight.
 *
 * NOT A REJECTION SAMPLE, which is what this replaces. The old loop called
 * `rollEssenceDrop` up to two hundred times and threw away everything under the
 * floor. That draws the right distribution -- conditioning a weighted draw on a
 * subset keeps the relative weights -- but it had a tail the right distribution
 * does not: when two hundred tries all came up short it fell through to
 * `ESSENCE_IDS.find(...)`, which is not a roll at all. It returns the FIRST
 * eligible essence in catalogue order, every time, for every player. A one-in-
 * a-million path that hands everyone the same essence is still a path, and it
 * is the one a bug report would eventually be about. Drawing from the pool
 * directly cannot miss, so there is no tail to get wrong.
 */
export function rollEssenceDropAtLeast(floor, rng = Math.random) {
  const ids = essencesAtLeast(floor);
  if (!ids.length) return null;
  const total = ids.reduce((a, id) => a + (ESSENCE_RARITY_WEIGHTS[ESSENCE_CATALOG[id].rarity] || 10), 0);
  let roll = rng() * total;
  for (const id of ids) {
    roll -= ESSENCE_RARITY_WEIGHTS[ESSENCE_CATALOG[id].rarity] || 10;
    if (roll <= 0) return id;
  }
  return ids[ids.length - 1];
}
